import {
	QueryCommand,
	UpdateItemCommand,
} from '@aws-sdk/client-dynamodb';
import { LambdaClient, InvokeCommand } from '@aws-sdk/client-lambda';
import { validateTenantAccess, assertHttpsUrls } from 'admin-auth';

const lambdaClient = new LambdaClient({ region: process.env.AWS_REGION });

// admin* phases are not on the public /amfa route (amfa-442 #1): invoke the
// login-service function directly with IAM. The tenant is the validated
// payload.id, never a body-supplied tenantid.
const invokeAmfa = async (id, body) => {
	const res = await lambdaClient.send(new InvokeCommand({
		FunctionName: process.env.AMFA_FUNCTION_ARN,
		Payload: JSON.stringify({
			headers: { Origin: `https://${id}.idapersona.${process.env.AMFA_BASE_URL}` },
			body: JSON.stringify(body),
		}),
	}));
	if (res.FunctionError) throw new Error(`amfa invoke failed: ${res.FunctionError}`);
	return JSON.parse(Buffer.from(res.Payload ?? []).toString() || '{}');
};

const updateSmtp = (id, smtp) => invokeAmfa(id, { phase: 'adminupdatesmtp', tenantid: id, smtp });

// GET no longer returns the password, so an omitted or empty `pass` on PUT means
// "keep the stored one"; it is read back server-side, never from the browser.
const fetchStoredPass = async (id) => {
	const res = await invokeAmfa(id, { phase: 'admingetsecretinfo', tenantid: id });
	const stored = JSON.parse(res.body || '{}').message;
	if (!stored || typeof stored !== 'object') throw new Error('Failed to fetch stored SMTP settings');
	return stored.pass;
};

export const putResData = async (event, payload, previousData, dynamodb) => {
	// Validate access using lambda layer
	const authResult = await validateTenantAccess(event, payload.id);
	
	if (!authResult.authorized) {
		const error = new Error(authResult.error || 'Access Denied');
		error.statusCode = authResult.statusCode || 403;
		throw error;
	}

	// Stored URLs are rendered as links in the Admin Portal (amfa-442 #9)
	assertHttpsUrls(payload, ['url', 'endUserSpUrl']);

	// First, query to get the current tenant and its sk
	const queryParams = {
		TableName: `amfa-tenanttable`,
		KeyConditionExpression: 'id = :id AND begins_with(sk, :sk_prefix)',
		ExpressionAttributeValues: {
			':id': { S: `TENANT#${payload.id}` },
			':sk_prefix': { S: 'TENANT#' }
		}
	};

	const queryResult = await dynamodb.send(new QueryCommand(queryParams));
	
	if (!queryResult.Items || queryResult.Items.length === 0) {
		const error = new Error(`Tenant ${payload.id} not found`);
		error.statusCode = 404;
		throw error;
	}

	const currentItem = queryResult.Items[0];
	const sk = currentItem.sk.S;

	// Update the tenant using composite key
	const now = new Date().toISOString();
	const updateParams = {
		TableName: `amfa-tenanttable`,
		Key: {
			id: { S: `TENANT#${payload.id}` },
			sk: { S: sk }
		},
		// org_id is not writable here: it drives SPA scoping (amfa-442 W3-3, D6).
		UpdateExpression: 'SET #name = :name, contact = :contact, #url = :url, endUserSpUrl = :endUserSpUrl, samlproxy = :samlproxy, updated_at = :updated_at',
		ExpressionAttributeNames: {
			'#name': 'name',
			'#url': 'url'
		},
		ExpressionAttributeValues: {
			':name': { S: payload.name },
			':contact': { S: payload.contact },
			':url': { S: payload.url },
			':endUserSpUrl': { S: payload.endUserSpUrl },
			// samlproxy is vestigial: SAML GW is always provisioned for every tenant.
			// Force true so legacy false records self-heal on edit.
			':samlproxy': { BOOL: true },
			':updated_at': { S: now }
		},
		ReturnValues: 'ALL_NEW'
	};

	const item = await dynamodb.send(new UpdateItemCommand(updateParams));

	const { pass, passConfigured, ...rest } = payload;
	const smtp = { host: previousData.host, port: previousData.port, user: previousData.user, secure: previousData.secure };
	const passChanged = Boolean(pass) && pass !== previousData.pass;
	const smtpChanged = passChanged || smtp.host !== payload.host || smtp.port !== payload.port || smtp.user !== payload.user || smtp.secure !== payload.secure;
	if (smtpChanged) {
		const smtp = {
			host: payload.host,
			port: payload.port,
			user: payload.user,
			pass: pass || (await fetchStoredPass(payload.id)) || '',
			secure: payload.secure ? 'true' : 'false',
		};
		await updateSmtp(payload.id, smtp);
	}

	return { ...rest, passConfigured: Boolean(pass) || Boolean(passConfigured) };
}

export default putResData;
